<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $user_id
 * @property string $token
 * @property string $platform
 * @property string|null $device_name
 * @property string|null $app_version
 * @property Carbon|null $last_used_at
 * @property Carbon|null $invalidated_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class DeviceToken extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'dvt';

    protected $fillable = [
        'user_id', 'token', 'platform', 'device_name', 'app_version', 'last_used_at', 'invalidated_at',
    ];

    protected function casts(): array
    {
        return [
            'last_used_at' => 'datetime',
            'invalidated_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }
}
